using System;using System.Collections.Generic;using TouristMoscowWP.ViewModel;using System.Windows.Media.Imaging;
class Program{static void Main(){var p=new MapItem();var es=new List<string>();p.PropertyChanged+=(s,e)=>es.Add(e.PropertyName);if(p.Image!=null)throw new Exception("Empty image must be absent");p.ImagePath="https://example.invalid/a.jpg";var first=(BitmapImage)p.Image;es.Clear();p.ImagePath="https://example.invalid/b.jpg";if(((BitmapImage)p.Image).UriSource.AbsoluteUri!="https://example.invalid/b.jpg"||!es.Contains("Image"))throw new Exception("Image cache stale after path change");p.ImagePath=null;if(p.Image!=null)throw new Exception("Null path retained image");var custom=new BitmapImage(new Uri("https://example.invalid/custom.jpg"));es.Clear();p.Image=custom;if(p.Image!=custom||!es.Contains("Image"))throw new Exception("Direct image assignment missing notification");p.SetImage("https://example.invalid/c.jpg");if(p.Image==custom)throw new Exception("SetImage retained direct image");Console.WriteLine("PASS: empty image, path replacement, clearing, direct assignment and SetImage");}}
